-- Reference year for the heat pump forecast (docs/warmtepomp.md): hourly outdoor
-- temperature (°C, 2 m) in 2019 at 52.01 N 4.73 E (the location of zone.home), hour 0 =
-- 2019-01-01 00:00 UTC. 2019 is the year of 2016-2025 whose heating degree days (base 16 °C,
-- 2010) are closest to the ten-year mean (1995).
-- Weather data by Open-Meteo.com (ERA5 reanalysis), CC BY 4.0: https://open-meteo.com/
-- Generated once; applied by install.sh after heat.sql (idempotent).
CREATE TABLE IF NOT EXISTS heat_reference (
    hour integer PRIMARY KEY,           -- 0 .. 8759, hours since 1 January 00:00 UTC
    temp double precision NOT NULL      -- °C
);
ON CONFLICT (hour) DO NOTHING;
